// 5. Health-check — public endpoint, no secret token
// ─────────────────────────────────────────────────────────────────
T.healthCheck = function(){
  var url = 'https://resonancemap.org/api/v1/sys/vc';
  return fetch(url, {method:'GET', cache:'no-store'})
    .then(function(r){
      if(!r.ok) throw new Error('HTTP '+r.status);
      return r.json();
    })
    .then(function(d){
      return {
        connected: true,
        mode: 'online',
        latticeVersion: d.latticeVersion || 'unknown',
        meshNodes: d.meshNodes || 0,
        genesisUrl: d.genesisUrl || T.config.genesis.url,
        checkedAt: new Date().toISOString(),
        endpoint: url
      };
    })
    .catch(function(err){
      return {
        connected: false,
        mode: 'offline',
        latticeVersion: T.config.version,
        meshNodes: 0,
        genesisUrl: T.config.genesis.url,
        checkedAt: new Date().toISOString(),
        endpoint: url,
        error: (err && err.message) || 'unreachable'
      };
    });
};

// ─────────────────────────────────────────────────────────────────
// 6. Local search — offline fallback (lattice + library)
// ─────────────────────────────────────────────────────────────────
T.localSearch = function(query){
  if(!query || typeof query!=='string') return {query:query, matches:[], books:[], nodes:[]};
  var q = query.toLowerCase();
  var words = q.split(/\s+/).filter(function(w){return w.length>2;});

  // Score books
  var bookScores = T.library.map(function(b,i){
    var hay = (b.title+' '+b.description+' '+b.keywords.join(' ')+' '+b.topicDomains.join(' ')).toLowerCase();
    var s = 0;
    words.forEach(function(w){ if(hay.indexOf(w)>=0) s++; });
    return {idx:i, score:s, book:b};
  }).filter(function(x){return x.score>0;}).sort(function(a,b){return b.score-a.score;}).slice(0,5);

  // Score lattice nodes
  var nodeScores = T.lattice.map(function(n){
    var hay = n.keywords.join(' ').toLowerCase();
    var s = 0;
    words.forEach(function(w){ if(hay.indexOf(w)>=0) s++; });
    return {nodeId:n.nodeId, score:s, keywords:n.keywords, band:n.band};
  }).filter(function(x){return x.score>0;}).sort(function(a,b){return b.score-a.score;}).slice(0,8);

  // Resonance via existing engine
  var res = T.resonate(query);

  return {
    query: query,
    resonance: res,
    books: bookScores.map(function(x){return {title:x.book.title, pages:x.book.pages, genre:x.book.genre, description:x.book.description, score:x.score};}),
    nodes: nodeScores,
    generatedAt: new Date().toISOString()
  };
};

